//! Golden-file tests of the first-party decoder plugins (ROADMAP P2 criterion 2).
//!
//! Every case feeds a committed SigMF reference recording (`tests/recordings/*.sigmf-*`,
//! generated by `scripts/gen-plugin-recordings.py`) to a plugin the way the host does, with the
//! real external tool behind it, and compares the events to `<name>.expected.jsonl`.
//!
//! The tools (multimon-ng, direwolf, rtl_433) must be installed; without them a case is skipped
//! with a note, unless `SUPERHET_REQUIRE_PLUGIN_TOOLS=1` (set in CI) turns that into a failure.
//! `UPDATE_GOLDEN=1 cargo test -p superhet-plugin-adapters --test golden` rewrites the expected
//! files; review the diff like any other change.

use std::path::{Path, PathBuf};
use std::time::Duration;

use serde_json::{Value, json};
use superhet_plugin_protocol::contract::{check, check_static, run_simple_with_env};
use superhet_plugin_protocol::manifest::SampleFormat;

const TIMEOUT: Duration = Duration::from_secs(60);

fn repo() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn recordings() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/recordings")
}

fn tool_available(tool: &str) -> bool {
    std::env::var_os("PATH")
        .is_some_and(|path| std::env::split_paths(&path).any(|dir| dir.join(tool).is_file()))
}

fn sigmf_datatype(format: SampleFormat) -> &'static str {
    match format {
        SampleFormat::Cu8 => "cu8",
        SampleFormat::Cs16 => "cs16_le",
        SampleFormat::Cf32 => "cf32_le",
        SampleFormat::S16le => "ri16_le",
        SampleFormat::F32le => "rf32_le",
    }
}

/// Run `recording` through `plugin` and compare with the expected events.
fn golden(plugin: &str, tool: &str, recording: &str, config: &Value) {
    golden_with(plugin, tool, recording, config, false);
}

/// The 16-bit samples negated: audio with the opposite polarity.
fn negate_s16(samples: &[u8]) -> Vec<u8> {
    samples
        .as_chunks::<2>()
        .0
        .iter()
        .flat_map(|b| i16::from_le_bytes(*b).saturating_neg().to_le_bytes())
        .collect()
}

/// [`golden`], optionally with the recording's audio inverted (expecting the same events).
fn golden_with(plugin: &str, tool: &str, recording: &str, config: &Value, invert: bool) {
    if !tool_available(tool) {
        assert!(
            std::env::var_os("SUPERHET_REQUIRE_PLUGIN_TOOLS").is_none(),
            "{tool} is required (SUPERHET_REQUIRE_PLUGIN_TOOLS is set) but not on PATH"
        );
        eprintln!("SKIP {plugin}/{recording}: {tool} is not installed");
        return;
    }
    let package = check_static(&repo().join("plugins").join(plugin))
        .unwrap_or_else(|problems| panic!("{plugin}: {problems:?}"));
    let input = package.manifest.input.as_ref().expect("decoder input");

    let meta: Value = serde_json::from_str(
        &std::fs::read_to_string(recordings().join(format!("{recording}.sigmf-meta")))
            .expect("sigmf-meta"),
    )
    .expect("sigmf-meta is JSON");
    assert_eq!(
        meta["global"]["core:datatype"],
        sigmf_datatype(input.format),
        "{recording}: datatype does not match the manifest"
    );
    assert_eq!(
        meta["global"]["core:sample_rate"], input.sample_rate,
        "{recording}: sample rate does not match the manifest"
    );
    let mut samples =
        std::fs::read(recordings().join(format!("{recording}.sigmf-data"))).expect("sigmf-data");
    if invert {
        samples = negate_s16(&samples);
    }

    // The manifests call `superhet-plugin-adapter` by name: put the freshly built binary first.
    let adapter = Path::new(env!("CARGO_BIN_EXE_superhet-plugin-adapter"))
        .parent()
        .expect("bin dir")
        .to_path_buf();
    let path = std::env::join_paths(std::iter::once(adapter).chain(std::env::split_paths(
        &std::env::var_os("PATH").unwrap_or_default(),
    )))
    .expect("PATH");
    let path = path.to_string_lossy().into_owned();
    let report =
        run_simple_with_env(&package, &samples, config, TIMEOUT, &[("PATH", &path)]).expect("run");
    let problems = check(&report);
    assert!(
        problems.is_empty(),
        "{plugin}/{recording}: {problems:?}\nstderr: {}",
        report.stderr
    );

    let actual: Vec<Value> = report
        .events
        .iter()
        .map(|e| json!({ "type": e.event_type, "data": e.data }))
        .collect();
    let expected_path = recordings().join(format!("{recording}.expected.jsonl"));
    if std::env::var_os("UPDATE_GOLDEN").is_some() && !invert {
        let text: String = actual.iter().map(|e| format!("{e}\n")).collect();
        std::fs::write(&expected_path, text).expect("write expected");
        return;
    }
    let expected: Vec<Value> = std::fs::read_to_string(&expected_path)
        .unwrap_or_else(|err| panic!("{}: {err}", expected_path.display()))
        .lines()
        .map(|line| serde_json::from_str(line).expect("expected line is JSON"))
        .collect();
    assert!(!expected.is_empty(), "{recording}: empty expectation");
    assert_eq!(
        actual, expected,
        "{plugin}/{recording}: events differ from the golden file\nstderr: {}",
        report.stderr
    );
}

#[test]
fn pocsag_mixed_baud_rates() {
    golden("pocsag", "multimon-ng", "pocsag-mixed", &Value::Null);
}

/// multimon-ng does not detect the polarity of POCSAG itself; the default `invert: "auto"` of the
/// adapter runs a second, inverted decoder, so audio with the opposite polarity gives the same pages.
#[test]
fn pocsag_inverted_audio_is_decoded_too() {
    golden_with("pocsag", "multimon-ng", "pocsag-mixed", &Value::Null, true);
}

/// FLEX is decoded in either polarity by one decoder; the pages must not appear twice.
#[test]
fn flex_inverted_audio_is_decoded_once() {
    golden_with("pocsag", "multimon-ng", "flex-1600", &Value::Null, true);
}

#[test]
fn flex_1600() {
    golden("pocsag", "multimon-ng", "flex-1600", &Value::Null);
}

#[test]
fn aprs_afsk1200() {
    golden("aprs", "direwolf", "aprs-afsk1200", &Value::Null);
}

#[test]
fn rtl433_nexus() {
    golden("rtl433", "rtl_433", "rtl433-nexus", &Value::Null);
}

#[test]
fn recordings_stay_small() {
    for entry in std::fs::read_dir(recordings())
        .expect("recordings dir")
        .flatten()
    {
        let size = entry.metadata().expect("metadata").len();
        assert!(
            size < 2_000_000,
            "{} is {size} bytes",
            entry.path().display()
        );
    }
}

#[test]
fn manifests_pass_static_checks() {
    for plugin in ["pocsag", "aprs", "rtl433"] {
        check_static(&repo().join("plugins").join(plugin))
            .unwrap_or_else(|problems| panic!("{plugin}: {problems:?}"));
    }
}

#[test]
fn missing_tool_exits_127_and_bad_config_exits_2() {
    let adapter = env!("CARGO_BIN_EXE_superhet-plugin-adapter");
    let status = std::process::Command::new(adapter)
        .arg("rtl433")
        .env("PATH", "")
        .stdin(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .expect("spawn");
    assert_eq!(status.code(), Some(127));
    let status = std::process::Command::new(adapter)
        .arg("pocsag")
        .env("SUPERHET_CONFIG", r#"{"baud":[7]}"#)
        .stdin(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .expect("spawn");
    assert_eq!(status.code(), Some(2));
}
